```ts
import { z } from 'zod'
const Cita = z.object({
  paciente: z.string().min(2),
  email: z.email(),
  fecha: z.coerce.date(),
})
type Cita = z.infer<typeof Cita> // el tipo sale gratis
const r = Cita.safeParse(req.body)
if (!r.success) return res.status(400).json({ errores: z.flattenError(r.error) })
```
- TypeScript **no** valida en tiempo de ejecución; Zod sí

```js
function requireRol(rol) {
  return (req, res, next) => {
    if (!req.user) return res.status(401).end()
    if (req.user.rol !== rol) return res.status(403).end()
    next()
  }
}
```

